　媒介｜業者は契約に立ち会うだけ｜片方から所定の額まで

・代理は業者が本人の名で契約を締結する（法律行為の代理）。媒介は当事者どうしの契約成立に向けて事実行為として尽力するだけである
・どちらも他人の取引への関与なので、貸借であっても免許が必要になる★
・国や地方公共団体から依頼されて代理・媒介をする業者自身は、当然に免許が必要である

━━━━━━━━━━━━━━━━━━━━━━
