　自ら貸借｜利用権が一時的に移るだけ｜借地借家法で保護済み★

・貸主と借主の関係は借地借家法という別の法律で手厚く保護されている。そのため宅建業法まで重ねて規制する必要が低いというのが立法趣旨である★
・一方、代理・媒介では業者が専門知識を武器に一般消費者と向き合うため、貸借であっても情報格差が生じる。だから貸借の代理・媒介は規制対象になる
・この趣旨を理解しておくと、「自ら貸借の場合は35条書面も37条書面も不要」「自ら貸借では報酬額の制限も受けない」といった応用問題にも即答できる★
・なお自ら貸借であっても、その業者が宅建業者である以上、他の取引について業法上の義務は当然に及ぶ。免許自体が不要になるのは、自ら貸借「しか」行っていない場合である★

