不動産取引は人生最大の買い物を扱います。だから、過去に悪質なことをした人にはしばらく免許を出しません。
「5年間ダメ」というグループと、「状態が続く限りダメ」というグループの2つがあります。
さらに、会社の場合は役員や重要な使用人が引っかかっていても会社が免許を取れません。
悪い人が名前を変えて会社を作り直す抜け道をふさぐ仕組みです。
数字とグループ分けを整理すれば、毎年出る免許の基準は確実に得点できます。

