【図解】5年待つ欠格事由
　事由｜起算点｜補足
　不正手段による免許取得等での免許取消し｜取消しの日から5年★｜三大取消事由
　業務停止処分違反での免許取消し｜取消しの日から5年★｜同上
　情状が特に重い不正不当行為での免許取消し｜取消しの日から5年★｜同上
　禁錮以上の刑に処せられた｜刑の執行を終わり又は執行を受けることがなくなった日から5年★｜罪名を問わない

・免許取消しで5年待つのは、いわゆる三大取消事由に限られる★。事務所の要件を欠いたことによる取消しなど他の事由では5年待たない
・三大取消事由で取消処分を受ける前に、聴聞の期日等の公示日から処分決定までの間に相当の理由なく廃業等の届出をした者も、届出の日から5年間免許を受けられない★（駆け込み廃業の防止）
・罰金刑で欠格になるのは、宅建業法違反、暴力団員による不当な行為の防止等に関する法律違反、傷害・現場助勢・暴行・凶器準備集合・脅迫・背任の罪、暴力行為等処罰に関する法律違反に限られる★
・執行猶予期間が満了すれば、その日から直ちに免許を受けられる★。5年待つ必要はない
