・「政令で定める使用人」とは、支店長・営業所長など、事務所の代表者として契約締結権限を有する者をいう
・監査役は原則として役員に含まれない★
・免許申請書やその添付書類に重要な事項について虚偽の記載があった場合、または重要な事実の記載が欠けている場合も免許は受けられない★

