　支払回数｜2回以上に分割して支払う★｜回数の要件
　対象｜宅地建物の売買★｜貸借は含まない

・割賦販売とは、代金の全部または一部について、目的物の引渡し後1年以上の期間にわたり、かつ2回以上に分割して受領することを条件とする売買をいう★
